SELECT country, city, CASE WHEN rating >= 4.2 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND(STDDEV(rating), 2) AS stddev_rating, SUM(CASE WHEN country = 'US' THEN 1 ELSE 0 END) AS us_count, SUM(rating) AS total_rating FROM suppliers WHERE city NOT IN ('Berlin', 'Bangkok', 'New York') GROUP BY country, city, CASE WHEN rating >= 4.2 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END
